helpers.log('Starting Set/Transform node execution');

const keepOnlySet = node.properties.keepOnlySet.value;
let valuesToSet = node.properties.values.value;

helpers.log(`Keep only set fields: ${keepOnlySet}`);
helpers.log(`Input data: ${JSON.stringify(data)}`);

// Parse values if it's a string
if (typeof valuesToSet === 'string' && valuesToSet.trim()) {
  try {
    valuesToSet = JSON.parse(valuesToSet);
    helpers.log(`Parsed values configuration: ${JSON.stringify(valuesToSet)}`);
  } catch (e) {
    helpers.error(`Failed to parse values JSON: ${e.message}`);
    return { error: 'Invalid JSON format for values to set', details: e.message };
  }
}

// Validate that valuesToSet is an array
if (!Array.isArray(valuesToSet)) {
  helpers.error('Values to set must be an array of {name, value} objects');
  return { error: 'Values to set must be an array' };
}

// Start with empty object if keepOnlySet is true, otherwise copy input data
const outputData = keepOnlySet ? {} : { ...data };

helpers.log(`Processing ${valuesToSet.length} field(s) to set/transform`);

// Set/transform each value
for (const item of valuesToSet) {
  if (!item.name) {
    helpers.warn('Skipping item without name property');
    continue;
  }

  const fieldName = String(item.name).trim();
  let fieldValue = item.value;

  // If value is undefined, set it to null
  if (fieldValue === undefined) {
    fieldValue = null;
  }

  helpers.log(`Setting field '${fieldName}' = ${JSON.stringify(fieldValue)}`);

  // Support nested field paths (e.g., "user.name")
  if (fieldName.includes('.')) {
    const parts = fieldName.split('.');
    let current = outputData;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      if (!current[part] || typeof current[part] !== 'object') {
        current[part] = {};
      }
      current = current[part];
    }

    current[parts[parts.length - 1]] = fieldValue;
  } else {
    outputData[fieldName] = fieldValue;
  }
}

helpers.log(`Output data: ${JSON.stringify(outputData)}`);
helpers.log('Set/Transform node execution completed successfully');

return outputData;
